    "factors.trauma.label": "4. Wrijving, Haken & Druk",
    "factors.trauma.opt_none": "Goed beschermd: geen directe slaapdruk, afgeschermd van strakke kleding, geen sportimpact",
    "factors.trauma.opt_occasional": "Af en toe licht blijven haken (licht contact met kleding of incidentele aanraking)",
